class RLEIterator:
    def __init__(self, encoding):
        self.q = []
        for i in range(0, len(encoding), 2):
            self.q.extend([encoding[i + 1]] * encoding[i])

    def next(self, n):
        if len(self.q) < n:
            self.q.clear()
            return -1
        val = -1
        for _ in range(n):
            val = self.q.pop(0)
        return val

