public:
    RLEIterator(vector<int>& encoding) {
        for (int i = 0; i < (int)encoding.size(); i += 2)
            for (long long k = 0; k < encoding[i]; k++)
                q.push_back(encoding[i + 1]);
    }
    int next(int n) {
        if ((long long)q.size() < n) { q.clear(); return -1; }
        int val = -1;
        while (n--) { val = q.front(); q.erase(q.begin()); }
        return val;
    }
private:
    vector<int> q;
};

