class RLEIterator:
    def __init__(self, encoding):
        self.enc = encoding
        self.idx = 0

    def next(self, n):
        while n > 0:
            if self.idx >= len(self.enc):
                return -1
            if self.enc[self.idx] >= n:
                self.enc[self.idx] -= n
                return self.enc[self.idx + 1]
            n -= self.enc[self.idx]
            self.idx += 2

